import CucumberSwiftGherkin
@testable import CucumberSwiftTestingGenerator
import XCTest

final class SwiftTestingSourceTests: XCTestCase {
    /// What the generator writes for one scenario, in full.
    static let eatAnApple = #"""
    // Generated by CucumberSwiftTestingPlugin from this target's feature files. Do not edit.
    //
    // One suite holds every feature in the target, and the features its Swift files write in the Swift
    // DSL, if they write any, in one test. The suite is serialized, because CucumberSwift runs one
    // scenario at a time, and step definitions often share state, unless parallel testing is on: the
    // environment variable CUCUMBER_PARALLEL_TESTING says so when Swift Testing discovers the tests,
    // or else the compilation condition of that name. A failed expectation is reported in the feature
    // file. Each test takes two lines, and the scenarios' contents come after all the
    // tests, so that editing a feature file moves no test: Xcode lists the tests from a copy of this
    // file that it doesn't always update, and matches results to them by line. These comments are here
    // rather than on the suite, where Swift Testing would show them with each failure.

    import CucumberSwiftTesting
    import Testing

    @MainActor
    @Suite("Features", CucumberSwiftTesting.cucumberScenarioOrder(compiled: cucumberParallelTesting), .reportedInFeatureFiles, .observedByCucumber)
    struct CucumberFeatures {
        @Test("Feature files are valid Gherkin")
        func gherkin() { cucumberGherkinProblems() }

        @MainActor
        @Suite("Eat fruit", .cucumberFeature(file: "/Features/Test.feature", title: "Eat fruit", line: 1), CucumberSwiftTesting.cucumberFeatureOrder(compiled: cucumberParallelTesting))
        struct EatFruit {
            @Test("Eat an apple", .serialized, .enabled { await CucumberSwiftTesting.Cucumber.shared.shouldRun(cucumberScenario1) },
                  arguments: await CucumberSwiftTesting.Cucumber.shared.casesToRun(cucumberScenario1))
            func EatAnApple(_ testCase: CucumberSwiftTesting.ScenarioCase) async throws { try await CucumberSwiftTesting.Cucumber.shared.run(testCase) }
        }
    }

    // MARK: - What the tests run

    #if CUCUMBER_PARALLEL_TESTING
    private let cucumberParallelTesting = true
    #else
    private let cucumberParallelTesting = false
    #endif

    /// Names the test bundle these tests are in, which the JSON report names its feature files and its copy after.
    private final class CucumberFeaturesBundle {}

    private func cucumberGherkinProblems() {
    }

    private let cucumberScenario1 = CucumberSwiftTesting.GherkinScenario(
        featureTitle: "Eat fruit",
        featureTags: ["fruit"],
        featureDescription: "",
        featureLine: 1,
        title: "Eat an apple",
        tags: ["fruit"],
        file: "/Features/Test.feature",
        testBundle: CucumberSwiftTesting.cucumberTestBundle(of: CucumberFeaturesBundle.self),
        line: 3,
        column: 3,
        steps: [
            CucumberSwiftTesting.GherkinStep(
                keyword: [.given],
                keywordName: "Given",
                keywordText: "Given",
                text: "an apple",
                line: 4,
                column: 5,
                suggestion: "Given(\"an apple\") { _, _ in\n    Issue.record(\"Step not implemented: replace this line with your test code\")\n}",
                regexLiteralSuggestion: "Given(#/^an apple$/#) { _, _ in\n    Issue.record(\"Step not implemented: replace this line with your test code\")\n}",
                bareSlashRegexLiteralSuggestion: "Given(/^an apple$/) { _, _ in\n    Issue.record(\"Step not implemented: replace this line with your test code\")\n}",
                macroSuggestion: "#Given(\"an apple\") {\n    Issue.record(\"Step not implemented: replace this line with your test code\")\n}",
                regexLiteralMacroSuggestion: "#Given(#/^an apple$/#) {\n    Issue.record(\"Step not implemented: replace this line with your test code\")\n}",
                bareSlashRegexLiteralMacroSuggestion: "#Given(/^an apple$/) {\n    Issue.record(\"Step not implemented: replace this line with your test code\")\n}")
        ])

    """#

    func generate(_ text: String, path: String = "/Features/Test.feature") -> String {
        SwiftTestingSource.generate([.init(path: path, file: FeatureFile(parsing: text, uri: path))])
    }

    func testAScenarioIsATestInItsFeaturesSuite() {
        let source = generate("""
        @fruit
        Feature: Eat fruit
          Scenario: Eat an apple
            Given an apple
        """)
        XCTAssertEqual(source, Self.eatAnApple)
    }

    func testAScenarioOutlineIsAParameterizedTestWithACaseForEachExample() {
        let source = generate("""
        Feature: Cukes
          Scenario Outline: Eat <eaten>
            Given I have <start> cukes
              | left   |
              | <left> |

            Examples:
              | start | eaten | left |
              | 12    | 5     | 7    |
              | 20    | 5     | 15   |
        """)
        XCTAssertTrue(source.contains(#"""
                @Test("Eat <eaten>", .serialized, arguments: await CucumberSwiftTesting.Cucumber.shared.casesToRun(cucumberExamples1))
                func EatEaten(_ testCase: CucumberSwiftTesting.ScenarioCase) async throws { try await CucumberSwiftTesting.Cucumber.shared.run(testCase) }
        """#), source)
        XCTAssertTrue(source.contains("private let cucumberExamples1 = [\n"), source)
        XCTAssertEqual(source.components(separatedBy: "CucumberSwiftTesting.GherkinExample(\n").count - 1, 2)
        XCTAssertTrue(source.contains(#"title: "Eat 5 (start: 12, left: 7)","#), source)
        XCTAssertTrue(source.contains(#"title: "Eat 5 (start: 20, left: 15)","#), source)
        XCTAssertTrue(source.contains(#"text: "I have 12 cukes","#), source)
        XCTAssertTrue(source.contains(#"dataTable: [["left"], ["15"]],"#), source)
        XCTAssertTrue(source.contains("line: 9,"), source)
        XCTAssertTrue(source.contains("line: 10,"), source)
    }

    func testEditingAFeatureFileMovesNoTest() {
        func tests(_ source: String) -> Substring {
            source[..<(source.range(of: "// MARK: - What the tests run")?.lowerBound ?? source.endIndex)]
        }
        let before = generate("""
        Feature: Cukes
          Scenario: Add cukes
            Given I have 1 cuke
          Scenario Outline: Eat cukes
            Given I eat <n>
            Examples:
              | n |
              | 1 |
        """)
        let after = generate("""
        @edited
        Feature: Cukes
          Add a description, a background, steps and examples.
          Background:
            Given a basket
          Scenario: Add cukes
            Given I have 1 cuke
            And I add 2 cukes
            Then I have 3 cukes
          Scenario Outline: Eat cukes
            Given I eat <n>
            Then I'm full
            Examples:
              | n |
              | 1 |
              | 2 |
        """)
        XCTAssertEqual(tests(before), tests(after))
    }

    func testStepsHaveTheirDocStringsAndContinuedKeywords() {
        let source = generate(#"""
        Feature: F
          Scenario: S
            Given a document
              """json
              {"a": "\(b)"}
              """
            And another step
        """#)
        XCTAssertTrue(source.contains(#"docString: CucumberSwiftTesting.DocString(literal: "{\"a\": \"\\(b)\"}", rawLiteral: "#), source)
        XCTAssertTrue(source.contains(#"contentType: "json")"#), source)
        XCTAssertTrue(source.contains("keyword: [.given, .and],"), source)
        XCTAssertTrue(source.contains(#"keywordName: "Given","#), source)
        // An `And` step counts as the keyword it continues, for the camel-case test names.
        XCTAssertTrue(source.contains(#"keywordName: "And","#), source)
        XCTAssertEqual(source.components(separatedBy: #"keywordText: "Given","#).count - 1, 2, source)
    }

    func testALocalizedFeatureFileIsReadInItsLanguage() {
        let source = generate("""
        # language: es
        Característica: Comer
          Escenario: Uno
            Dado un paso
        """)
        XCTAssertTrue(source.contains("struct Comer {"), source)
        XCTAssertTrue(source.contains("func Uno(_ testCase: CucumberSwiftTesting.ScenarioCase) async throws {"), source)
        XCTAssertTrue(source.contains("keyword: [.given],"), source)
        XCTAssertTrue(source.contains(#"text: "un paso","#), source)
        XCTAssertTrue(source.contains(#"keywordName: "Dado","#), source)
        XCTAssertTrue(source.contains(#"keywordText: "Dadas","#), source)
    }

    func testFeaturesWrittenInTheSwiftDSLAreOneTestAfterTheGherkinTest() {
        let source = SwiftTestingSource.generate([], dslFeatures: true)
        let test = #"""
                func gherkin() { cucumberGherkinProblems() }

                @Test("Swift DSL features", arguments: await CucumberSwiftTesting.Cucumber.shared.dslCasesToRun(parallelCompiled: cucumberParallelTesting, \#
            testBundle: CucumberSwiftTesting.cucumberTestBundle(of: CucumberFeaturesBundle.self)))
                func swiftDSL(_ testCase: CucumberSwiftTesting.ScenarioCase) async throws { try await CucumberSwiftTesting.Cucumber.shared.run(testCase) }
            }
            """#
        XCTAssertTrue(source.contains(test), source)
        XCTAssertFalse(generate("Feature: F\n").contains("Swift DSL features"))
    }

    func testATargetWithNeitherFeatureFilesNorTheSwiftDSLGetsNoTests() {
        XCTAssertFalse(SwiftTestingSource.generate([]).contains("@Test"))
    }

    func testASwiftFileWritesDSLFeaturesWhenItCallsFeatureOrALocalizedType() {
        XCTAssertTrue(SwiftTestingSource.writesDSLFeatures(#"Feature("Checkout") {"#))
        XCTAssertTrue(SwiftTestingSource.writesDSLFeatures("CucumberSwiftTesting.Feature (\"A\") {"))
        XCTAssertTrue(SwiftTestingSource.writesDSLFeatures(#"ES_Característica("Caja") {"#))
        XCTAssertTrue(SwiftTestingSource.writesDSLFeatures(#"EN_PIRATE_Ahoymatey("Arr") {"#))
        XCTAssertFalse(SwiftTestingSource.writesDSLFeatures(#"#Given("I have {int} cukes") { (count: Int) in }"#))
        XCTAssertFalse(SwiftTestingSource.writesDSLFeatures(#"#ES_Dado("tengo {int} pepinos") { (count: Int) in }"#))
        XCTAssertFalse(SwiftTestingSource.writesDSLFeatures("BeforeFeature { feature in }"))
        XCTAssertFalse(SwiftTestingSource.writesDSLFeatures("let feature = makeFeature()"))
    }

    func testValidFeatureFilesStillHaveTheGherkinTest() {
        XCTAssertTrue(generate("Feature: F\n").contains(#"@Test("Feature files are valid Gherkin")"#))
    }

    func testProblemsInAFeatureFileFailATest() {
        let source = generate("# language: xx\nFeature: F\n  Scenario: S\n    Given a step\n", path: "/Features/Bad.feature")
        XCTAssertTrue(source.contains(#"@Test("Feature files are valid Gherkin")"#), source)
        let location = #"SourceLocation(fileID: "Features/Bad.feature", filePath: "/Features/Bad.feature", line: 1, column: 1)"#
        XCTAssertTrue(source.contains(#"Issue.record("File: Bad.feature declares an unsupported language", sourceLocation: "# + location + ")"), source)
    }

    func testAFeatureWithoutScenariosHasNoSuite() {
        XCTAssertFalse(generate("Feature: Empty\n").contains("struct Empty"))
    }

    func testNamesAreUniqueAndNeverHideWhatTheGeneratedCodeUses() {
        var used = Set<String>()
        XCTAssertEqual(SwiftTestingSource.uniqueName("EatCukes", fallback: "Scenario", in: &used), "EatCukes")
        XCTAssertEqual(SwiftTestingSource.uniqueName("EatCukes", fallback: "Scenario", in: &used), "EatCukes_2")
        XCTAssertEqual(SwiftTestingSource.uniqueName("", fallback: "Scenario", in: &used), "Scenario")
        XCTAssertEqual(SwiftTestingSource.uniqueName("Test", fallback: "Scenario", in: &used), "Scenario_2")
        XCTAssertEqual(SwiftTestingSource.uniqueName("CucumberSwiftTesting", fallback: "Feature", in: &used), "Feature")
    }

    func testTwoScenariosWithTheSameTitleGetTwoTests() {
        let source = generate("""
        Feature: F
          Scenario: Same
            Given a step
          Scenario: Same
            Given a step
          Scenario: 🥒
            Given a step
        """)
        XCTAssertTrue(source.contains("func Same(_ testCase: CucumberSwiftTesting.ScenarioCase) async throws {"), source)
        XCTAssertTrue(source.contains("func Same_2(_ testCase: CucumberSwiftTesting.ScenarioCase) async throws {"), source)
        XCTAssertTrue(source.contains(#"@Test("🥒", .serialized, .enabled"#), source)
        XCTAssertTrue(source.contains("func Scenario(_ testCase: CucumberSwiftTesting.ScenarioCase) async throws {"), source)
    }

    func testTextIsAlwaysAValidStringLiteral() {
        XCTAssertEqual(SwiftTestingSource.literal(#"a "quoted" \(interpolation)"#), #""a \"quoted\" \\(interpolation)""#)
        XCTAssertEqual(SwiftTestingSource.literal("two\nlines\tand\r\u{0}"), #""two\nlines\tand\r\u{0}""#)
        XCTAssertEqual(SwiftTestingSource.literal("Pepinos en español 🥒"), "\"Pepinos en español 🥒\"")
    }
}
